// Default prompt for Upscale style - auto-fills when user selects "upscale"
const UPSCALE_DEFAULT_PROMPT = "Upscale and enhance this low-resolution image to high clarity while maintaining the original identity and natural appearance. Restore fine textures, edges, and micro-details without inventing unrealistic features. Remove noise, artifacts, and compression blocks. Do not change the pose, lighting, clothing, or background. Keep the improvement subtle, natural, and faithful to the original.";

/**
 * Parse skill output for "both" mode (image_video_generation skills)
 * Extracts header (title, character, environment) + image prompts vs video prompts
 */
function parseSkillOutputForBothMode(content: string): { imagePrompt: string; videoPrompt: string } | null {
  // Detect image prompts section (English or Thai) - match **Image Prompts:** or **Prompt สร้างภาพ:**
  const imagePromptPatterns = [
    /\*\*Image Prompts:?\*\*/i,
    /\*\*Prompt สร้างภาพ:?\*\*/i,
  ];

  // Detect video prompts section (English or Thai)
  const videoPromptPatterns = [
    /\*\*Video Prompts:?\*\*/i,
    /\*\*Prompt สร้างวิดีโอ:?\*\*/i,
  ];

  // Find the positions of image and video sections
  let imageStart = -1;
  let videoStart = -1;

  for (const pattern of imagePromptPatterns) {
    const match = content.search(pattern);
    if (match !== -1 && (imageStart === -1 || match < imageStart)) {
      imageStart = match;
    }
  }

  for (const pattern of videoPromptPatterns) {
    const match = content.search(pattern);
    if (match !== -1 && (videoStart === -1 || match < videoStart)) {
      videoStart = match;
    }
  }

  // If both sections not found, return null (don't split)
  if (imageStart === -1 || videoStart === -1) {
    return null;
  }

  // Extract header (everything before the first prompt section)
  const firstSectionStart = Math.min(imageStart, videoStart);
  const header = content.substring(0, firstSectionStart).trim();

  // Determine section order and extract prompts
  let imageSection: string;
  let videoSection: string;

  if (imageStart < videoStart) {
    // Image section comes first
    imageSection = content.substring(imageStart, videoStart).trim();
    videoSection = content.substring(videoStart).trim();
  } else {
    // Video section comes first
    videoSection = content.substring(videoStart, imageStart).trim();
    imageSection = content.substring(imageStart).trim();
  }

  // Combine header with each section
  const imagePrompt = `${header}\n\n${imageSection}`;
  const videoPrompt = `${header}\n\n${videoSection}`;

  return { imagePrompt, videoPrompt };
}

function stripJsonMarkdownFence(content: string): string {
  const trimmed = content.trim();
  const fenced = trimmed.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
  return fenced?.[1]?.trim() || trimmed;
}

function extractPromptTextFromStructuredSkillOutput(value: unknown): string | null {
  if (typeof value === "string") {
    const trimmed = value.trim();
    return trimmed || null;
  }

  if (Array.isArray(value)) {
    const parts = value
      .map((item) => extractPromptTextFromStructuredSkillOutput(item))
      .filter((item): item is string => Boolean(item));
    return parts.length > 0 ? parts.join("\n\n") : null;
  }

  if (!value || typeof value !== "object") {
    return null;
  }

  const record = value as Record<string, unknown>;
  const directKeys = ["prompt", "promptText", "text", "content", "result"];
  for (const key of directKeys) {
    const extracted = extractPromptTextFromStructuredSkillOutput(record[key]);
    if (extracted) return extracted;
  }

  const nestedKeys = ["output", "data"];
  for (const key of nestedKeys) {
    const extracted = extractPromptTextFromStructuredSkillOutput(record[key]);
    if (extracted) return extracted;
  }

  const prompts = extractPromptTextFromStructuredSkillOutput(record.prompts);
  if (prompts) return prompts;

  return null;
}

function normalizeCustomSkillPromptContent(content: string): string {
  const trimmed = content.trim();
  if (!trimmed) return content;

  const jsonCandidate = stripJsonMarkdownFence(trimmed);
  if (!/^[\[{]/.test(jsonCandidate)) {
    return content;
  }

  try {
    const parsed = JSON.parse(jsonCandidate);
    return extractPromptTextFromStructuredSkillOutput(parsed) || content;
  } catch {
    return content;
  }
}

function parseJsonSkillContent(content: string): Record<string, any> | null {
  const trimmed = stripJsonMarkdownFence(content.trim());
  if (!trimmed || !/^[\[{]/.test(trimmed)) return null;
  try {
    const parsed = JSON.parse(trimmed);
    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
      return parsed as Record<string, any>;
    }
    return { items: parsed };
  } catch {
    return null;
  }
}

function buildProductionRunId(): string {
  const randomPart = Math.random().toString(36).slice(2, 10);
  return `prod-${Date.now().toString(36)}-${randomPart}`;
}

function getProductionPlanScenes(plan: Record<string, any> | null | undefined): any[] {
  if (!plan) return [];
  const candidates = [
    plan.storyboard_outline,
    plan.storyboardOutline,
    plan.scene_timeline,
    plan.sceneTimeline,
    plan.shot_plan,
    plan.shotPlan,
    plan.prompt_sequence,
  ];
  for (const candidate of candidates) {
    if (Array.isArray(candidate)) return candidate;
  }
  return [];
}

function resolveProductionStoryboardTiming(params: {
  totalDurationSeconds?: unknown;
  clipDurationSeconds?: unknown;
}): { totalDurationSeconds: number; clipDurationSeconds: number; shotCount: number } {
  const clipDurationSeconds = Math.max(
    1,
    Math.round(Number(params.clipDurationSeconds) || DEFAULT_STORYBOARD_CLIP_DURATION_SECONDS),
  );
  const totalDurationSeconds = Math.max(
    clipDurationSeconds,
    Math.round(Number(params.totalDurationSeconds) || clipDurationSeconds),
  );
  return {
    totalDurationSeconds,
    clipDurationSeconds,
    shotCount: Math.max(1, Math.ceil(totalDurationSeconds / clipDurationSeconds)),
  };
}

function normalizeProductionStoryboardShots(params: {
  inputShots: any[];
  fallbackScenes?: any[];
  timing: { totalDurationSeconds: number; clipDurationSeconds: number; shotCount: number };
  locale: "th" | "en";
}): any[] {
  const candidates = params.inputShots.length ? params.inputShots : params.fallbackScenes ?? [];
  const fallbackTitle = params.locale === "th" ? "Shot" : "Shot";
  return Array.from({ length: params.timing.shotCount }, (_, index) => {
    const source = candidates[index] ?? candidates[candidates.length - 1] ?? {};
    const remainingSeconds = params.timing.totalDurationSeconds - (params.timing.clipDurationSeconds * index);
    const durationSeconds = index === params.timing.shotCount - 1
      ? Math.max(1, Math.min(params.timing.clipDurationSeconds, remainingSeconds))
      : params.timing.clipDurationSeconds;
    const order = index + 1;
    return {
      ...source,
      id: String(source.id ?? source.shot_id ?? `shot-${order}`),
      title: String(source.title ?? source.scene_title ?? source.shot_title ?? `${fallbackTitle} ${order}`),
      order,
      durationSeconds,
      storyBeat: String(source.storyBeat ?? source.story_beat ?? source.description ?? source.detail ?? ""),
      shotType: String(source.shotType ?? source.shot_type ?? (index === 0 ? "hook" : "demo")),
      script: String(source.script ?? source.voiceover ?? source.narration ?? source.storyBeat ?? source.story_beat ?? ""),
      visualIntent: String(source.visualIntent ?? source.visual_intent ?? source.visual ?? ""),
      audioIntent: String(source.audioIntent ?? source.audio_intent ?? source.audio ?? ""),
      cameraIntent: String(source.cameraIntent ?? source.camera_intent ?? source.camera ?? ""),
      nodeIds: [`shot-${order}-group`],
      status: source.status ?? "draft",
    };
  });
}

function getProductionPlanSummary(plan: Record<string, any> | null | undefined): string {
  if (!plan) return "";
  const summary = plan.production_goal_summary ?? plan.goal_summary ?? plan.summary;
  if (typeof summary === "string") return summary;
  const strategy = plan.creative_strategy ?? plan.creativeStrategy;
  if (typeof strategy === "string") return strategy;
  if (strategy && typeof strategy === "object") {
    return Object.values(strategy).filter((value) => typeof value === "string").slice(0, 2).join(" ");
  }
  return "";
}

function buildGenericProductionPromptFromPlan(plan: Record<string, any>, targetModelName: string): string {
  const scenes = getProductionPlanScenes(plan).slice(0, 12);
  const summary = getProductionPlanSummary(plan);
  const strategy = plan.creative_strategy ?? plan.creativeStrategy ?? {};
  const strategyText = typeof strategy === "string"
    ? strategy
    : strategy && typeof strategy === "object"
      ? Object.values(strategy).filter((value) => typeof value === "string").slice(0, 4).join("\n")
      : "";
  const sceneText = scenes.map((scene, index) => {
    const title = String((scene as any)?.title ?? (scene as any)?.scene_title ?? (scene as any)?.shot_title ?? `Scene ${index + 1}`);
    const prompt = String(
      (scene as any)?.prompt
      ?? (scene as any)?.video_prompt
      ?? (scene as any)?.description
      ?? (scene as any)?.summary
      ?? "",
    );
    return `${index + 1}. ${title}${prompt ? `: ${prompt}` : ""}`;
  }).join("\n");
  return [
    `Target video model: ${targetModelName || "selected video model"}`,
    summary ? `Production goal: ${summary}` : "",
    strategyText ? `Creative direction:\n${strategyText}` : "",
    sceneText ? `Storyboard / shot plan:\n${sceneText}` : "",
    "Generate a cinematic, coherent video prompt from this approved production plan. Preserve product truth, character continuity, pacing, and platform intent.",
  ].filter(Boolean).join("\n\n");
}

function buildProductionTabSnapshot(tabState: TabState) {
  return {
    prompt: tabState.prompt,
    enhancedPrompt: tabState.enhancedPrompt,
    selectedModel: tabState.selectedModel,
    aspectRatio: tabState.aspectRatio,
    duration: tabState.duration,
    numImages: tabState.numImages,
    modelInputValues: tabState.modelInputValues,
    referenceImages: tabState.referenceImages,
    referenceVideos: tabState.referenceVideos,
    selectedSkillId: tabState.selectedSkillId,
    useAdvancedMode: tabState.useAdvancedMode,
    dynamicFormValues: tabState.dynamicFormValues,
    geminiOmni: tabState.geminiOmni,
  };
}

function applyProductionTabSnapshotsToState(
  prev: Record<MediaType, TabState>,
  snapshots: Record<string, any> | null | undefined,
): Record<MediaType, TabState> {
  if (!snapshots || typeof snapshots !== "object") return prev;
  const next = { ...prev };
  (["image", "video", "audio"] as MediaType[]).forEach((tab) => {
    const snapshot = snapshots[tab];
    if (!snapshot || typeof snapshot !== "object") return;
    next[tab] = {
      ...next[tab],
      prompt: typeof snapshot.prompt === "string" ? snapshot.prompt : next[tab].prompt,
      enhancedPrompt: typeof snapshot.enhancedPrompt === "string" ? snapshot.enhancedPrompt : next[tab].enhancedPrompt,
      selectedModel: typeof snapshot.selectedModel === "string" ? snapshot.selectedModel : next[tab].selectedModel,
      aspectRatio: typeof snapshot.aspectRatio === "string" ? snapshot.aspectRatio : next[tab].aspectRatio,
      duration: typeof snapshot.duration === "number" ? snapshot.duration : next[tab].duration,
      numImages: typeof snapshot.numImages === "number" ? snapshot.numImages : next[tab].numImages,
      modelInputValues: snapshot.modelInputValues && typeof snapshot.modelInputValues === "object" ? snapshot.modelInputValues : next[tab].modelInputValues,
      referenceImages: Array.isArray(snapshot.referenceImages) ? snapshot.referenceImages : next[tab].referenceImages,
      referenceVideos: Array.isArray(snapshot.referenceVideos) ? snapshot.referenceVideos : next[tab].referenceVideos,
      selectedSkillId: typeof snapshot.selectedSkillId === "string" ? snapshot.selectedSkillId : next[tab].selectedSkillId,
      useAdvancedMode: typeof snapshot.useAdvancedMode === "boolean" ? snapshot.useAdvancedMode : next[tab].useAdvancedMode,
      dynamicFormValues: snapshot.dynamicFormValues && typeof snapshot.dynamicFormValues === "object" ? snapshot.dynamicFormValues : next[tab].dynamicFormValues,
      geminiOmni: snapshot.geminiOmni && typeof snapshot.geminiOmni === "object"
        ? { ...next[tab].geminiOmni, ...snapshot.geminiOmni }
        : next[tab].geminiOmni,
    };
  });
  return next;
}

function normalizeGeminiOmniVideoQaResult(value: Record<string, any> | null | undefined): {
  status: NonNullable<GenerationTask["videoQaStatus"]>;
  score: number;
  issues: SkillImprovementIssue[];
  proposedChanges: SkillImprovementProposedChange[];
  summary: string;
} {
  const record = value ?? {};
  const verdict = String(record.verdict ?? record.status ?? record.recommended_action ?? "human_review").toLowerCase();
  const status: NonNullable<GenerationTask["videoQaStatus"]> =
    verdict === "pass" || verdict === "accept" || verdict === "approve"
      ? "pass"
      : verdict === "warning"
        ? "warning"
        : verdict === "revise" || verdict === "regenerate_same_prompt" || verdict === "revise_video_prompt"
          ? "revise"
          : verdict === "block"
            ? "block"
            : "human_review";
  const score = Math.max(0, Math.min(100, Number(
    record.score
      ?? record.quality_score
      ?? record.qualityScores?.overall
      ?? record.quality_scores?.overall
      ?? (status === "pass" ? 90 : status === "warning" ? 75 : 55),
  ) || 0));
  const rawIssues = Array.isArray(record.issues)
    ? record.issues
    : Array.isArray(record.blocking_issues)
      ? record.blocking_issues
      : [];
  const issues = rawIssues.slice(0, 8).map((issue: any, index: number): SkillImprovementIssue => ({
    id: String(issue.id ?? issue.code ?? issue.category ?? `video_qa_issue_${index + 1}`).slice(0, 100),
    severity: issue.severity === "high" || issue.severity === "medium" || issue.severity === "low"
      ? issue.severity
      : status === "block" || status === "revise"
        ? "high"
        : "medium",
    title: String(issue.title ?? issue.message ?? issue.category ?? `Video QA issue ${index + 1}`).slice(0, 255),
    evidence: typeof issue.evidence === "string" ? issue.evidence.slice(0, 2000) : undefined,
    recommendation: String(issue.recommendation ?? issue.recommended_action ?? issue.fix ?? "Improve Gemini Omni prompt/director instructions for this issue.").slice(0, 2000),
    affectedSection: String(issue.affected_section ?? issue.affectedSection ?? "Gemini Omni video quality").slice(0, 255),
  }));
  const rawLearningSignals = Array.isArray(record.learning_signal_candidates)
    ? record.learning_signal_candidates
    : Array.isArray(record.learningSignals)
      ? record.learningSignals
      : [];
  const signalIssues = rawLearningSignals.slice(0, 6).map((signal: any, index: number): SkillImprovementIssue => ({
    id: String(signal.id ?? signal.issue_category ?? signal.category ?? `video_qa_learning_${index + 1}`).slice(0, 100),
    severity: signal.severity === "high" || signal.severity === "medium" || signal.severity === "low" ? signal.severity : "medium",
    title: String(signal.title ?? signal.issue_category ?? signal.category ?? `Video QA learning signal ${index + 1}`).slice(0, 255),
    evidence: typeof signal.evidence === "string" ? signal.evidence.slice(0, 2000) : undefined,
    recommendation: String(signal.recommendation ?? signal.suggested_change ?? "Review Gemini Omni director guidance for recurring video quality failures.").slice(0, 2000),
    affectedSection: String(signal.affected_section ?? "Video QA learning").slice(0, 255),
  }));
  const mergedIssues = issues.length > 0 ? issues : signalIssues;
  const revisionInstructions = Array.isArray(record.revision_instructions)
    ? record.revision_instructions
    : Array.isArray(record.revisionInstructions)
      ? record.revisionInstructions
      : [];
  const proposedChanges: SkillImprovementProposedChange[] = mergedIssues.length > 0
    ? [{
      title: "Improve Gemini Omni video director QA recovery guidance",
      reason: revisionInstructions.map(String).join(" ").slice(0, 2000)
        || "Video QA found recurring issues that should inform prompt/director instructions.",
      targetFile: "apps/web/skills/gemini-omni-video-director/SKILL.md",
      targetSection: "Quality recovery and revision guidance",
      risk: mergedIssues.some((issue) => issue.severity === "high") ? "medium" : "low",
    }]
    : [];
  const summary = String(
    record.summary
      ?? record.reviewer_notes
      ?? record.reviewerNotes
      ?? `${status} (${score}/100)`,
  ).slice(0, 500);
  return { status, score, issues: mergedIssues, proposedChanges, summary };
}

function parseArrayFieldValue(
  raw: unknown,
  options: { splitLines?: boolean } = {},
): unknown[] {
  const splitLines = options.splitLines ?? true;
  if (Array.isArray(raw)) return raw;
  if (raw === null || raw === undefined) return [];

  if (typeof raw === "string") {
    const trimmed = raw.trim();
    if (!trimmed) return [];
    try {
      const parsed = JSON.parse(trimmed);
      if (Array.isArray(parsed)) return parsed;
      return [parsed];
    } catch {
      if (!splitLines) {
        return [trimmed];
      }
      return trimmed
        .split(/\r?\n/)
        .map((line) => line.trim())
        .filter((line) => line.length > 0);
    }
  }

  return [raw];
}

function getTemplatePathValue(source: unknown, path: string): unknown {
  const segments = path.split(".").filter(Boolean);
  let current: unknown = source;
  for (const segment of segments) {
    if (current === null || current === undefined || typeof current !== "object") {
      return undefined;
    }
    current = (current as Record<string, unknown>)[segment];
  }
  return current;
}

function interpolateTemplate(template: unknown, context: Record<string, unknown>): unknown {
  if (typeof template === "string") {
    const tokenPattern = /\{\{\s*([^}]+)\s*\}\}/g;
    const fullToken = template.match(/^\s*\{\{\s*([^}]+)\s*\}\}\s*$/);
    if (fullToken) {
      const fullPath = fullToken[1]?.trim();
      if (fullPath) {
        const fullValue = getTemplatePathValue(context, fullPath);
        return fullValue ?? "";
      }
      return "";
    }
    return template.replace(tokenPattern, (_match, rawPath: string) => {
      const path = rawPath.trim();
      const value = path ? getTemplatePathValue(context, path) : undefined;
      return value === null || value === undefined ? "" : String(value);
    });
  }

  if (Array.isArray(template)) {
    return template.map((item) => interpolateTemplate(item, context));
  }

  if (template && typeof template === "object") {
    const out: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(template as Record<string, unknown>)) {
      out[key] = interpolateTemplate(value, context);
    }
    return out;
  }

  return template;
}

function resolveArrayFieldRuntimeValue(
  field: Record<string, any>,
  rawValue: unknown,
  context: Record<string, unknown>
): unknown[] {
  const syncWith = inferModelInputSyncTarget(field);
  if (syncWith === "prompt" && field.promptSync?.strategy === "speaker_lines") {
    const speakerLineItems = buildSpeakerLineArrayRuntimeValue(field, String(rawValue || ""), context);
    if (speakerLineItems) {
      return speakerLineItems;
    }
  }

  // Prompt-synced array fields should default to a single item (full prompt),
  // while user-entered array strings can still use newline splitting.
  const splitLines = syncWith === "prompt" ? false : true;
  const items = parseArrayFieldValue(rawValue, { splitLines });
  const template = field.itemTemplate;
  if (!template) {
    return items;
  }

  return items.map((item, index) => {
    const resolvedTemplate = interpolateTemplate(template, {
      ...context,
      value: item,
      item,
      index,
    });

    // Structured array editors return objects such as { speaker, voice }.
    // Keep those user-selected values as the source of truth while allowing
    // itemTemplate to fill missing defaults.
    if (item && typeof item === "object" && !Array.isArray(item)) {
      return {
        ...(resolvedTemplate && typeof resolvedTemplate === "object" && !Array.isArray(resolvedTemplate)
          ? resolvedTemplate as Record<string, unknown>
          : {}),
        ...(item as Record<string, unknown>),
      };
    }

    return resolvedTemplate;
  });
}

function buildSpeakerLineArrayRuntimeValue(
  field: Record<string, any>,
  promptText: string,
  context: Record<string, unknown>,
): unknown[] | null {
  const promptSync = field.promptSync && typeof field.promptSync === "object"
    ? field.promptSync as Record<string, unknown>
    : {};
  const textKey = typeof promptSync.textKey === "string" && promptSync.textKey.trim()
    ? promptSync.textKey.trim()
    : "text";
  const defaultVoiceField = typeof promptSync.defaultVoiceField === "string" && promptSync.defaultVoiceField.trim()
    ? promptSync.defaultVoiceField.trim()
    : "voice_id";
  const rawSpeakerVoiceFields = promptSync.speakerVoiceFields && typeof promptSync.speakerVoiceFields === "object" && !Array.isArray(promptSync.speakerVoiceFields)
    ? promptSync.speakerVoiceFields as Record<string, unknown>
    : {};
  const speakerVoiceFields = Object.fromEntries(
    Object.entries(rawSpeakerVoiceFields)
      .filter((entry): entry is [string, string] => typeof entry[1] === "string" && entry[1].trim().length > 0)
      .map(([speaker, voiceField]) => [speaker, voiceField.trim()]),
  );
  const speakerPattern = typeof promptSync.speakerPattern === "string" && promptSync.speakerPattern.trim()
    ? promptSync.speakerPattern
    : "^\\s*Speaker\\s*(\\d+)\\s*[:：-]\\s*(.*)$";

  let speakerRegex: RegExp;
  try {
    speakerRegex = new RegExp(speakerPattern, "i");
  } catch {
    speakerRegex = /^\s*Speaker\s*(\d+)\s*[:：-]\s*(.*)$/i;
  }

  const segments: Array<{ speaker: string; text: string }> = [];
  let currentSpeaker: string | null = null;
  let currentLines: string[] = [];
  const flush = () => {
    const text = currentLines.join("\n").trim();
    if (currentSpeaker && text) {
      segments.push({ speaker: currentSpeaker, text });
    }
    currentLines = [];
  };

  for (const rawLine of promptText.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line) continue;
    const match = line.match(speakerRegex);
    if (match) {
      flush();
      currentSpeaker = String(match[1] || "1");
      const firstLine = String(match[2] || "").trim();
      currentLines = firstLine ? [firstLine] : [];
      continue;
    }
    if (currentSpeaker) {
      currentLines.push(line);
    }
  }
  flush();

  if (segments.length === 0) {
    return null;
  }

  const fields = context.fields && typeof context.fields === "object"
    ? context.fields as Record<string, unknown>
    : {};
  return segments.map((segment) => {
    const voiceField = speakerVoiceFields[segment.speaker] || defaultVoiceField;
    return {
      [textKey]: segment.text,
      voice_id: fields[voiceField] ?? fields[defaultVoiceField],
    };
  });
}

function buildRuntimeExtraParamsFromModelInputs(params: {
  model: any;
  inputValues: Record<string, unknown>;
  prompt: string;
  aspectRatio?: string;
  activeTab: MediaType;
}): Record<string, unknown> {
  const modelConfig = parseMediaModelConfig(params.model?.configJson);
  const inputFields = Array.isArray(modelConfig?.inputFields)
    ? modelConfig.inputFields as Record<string, any>[]
    : [];
  const templateBaseContext = {
    prompt: params.prompt,
    aspectRatio: params.aspectRatio,
    activeTab: params.activeTab,
    fields: params.inputValues,
  } as Record<string, unknown>;
  const extraParams: Record<string, unknown> = {};

  for (const field of inputFields) {
    const syncWith = inferModelInputSyncTarget(field);
    const resolveFieldValue = (value: unknown): unknown => (
      field.type === "array"
        ? resolveArrayFieldRuntimeValue(field, value, templateBaseContext)
        : value
    );

    if (syncWith === "prompt") {
      extraParams[field.key] = resolveFieldValue(params.prompt);
      continue;
    }
    if (syncWith === "aspect_ratio") {
      extraParams[field.key] = resolveFieldValue(params.aspectRatio ?? "");
      continue;
    }
    if (syncWith === "reference_images" || syncWith === "reference_videos") {
      continue;
    }

    const rawValue = params.inputValues[field.key] ?? field.default;
    const value = resolveFieldValue(rawValue);
    if (field.key === "language_code" && String(value) === "__auto__") {
      continue;
    }
    if (field.includeInPayload === false) {
      continue;
    }
    if (
      value !== undefined
      && value !== null
      && value !== ""
      && !(Array.isArray(value) && value.length === 0)
    ) {
      extraParams[field.key] = value;
    }
  }

  return extraParams;
}

function countCharactersForPricing(value: unknown, options: { ignoreWhitespace?: boolean } = {}): number {
  const ignoreWhitespace = options.ignoreWhitespace === true;
  if (value === null || value === undefined) return 0;
  if (typeof value === "string") {
    return ignoreWhitespace ? value.replace(/\s+/g, "").length : value.length;
  }
  if (Array.isArray(value)) {
    return value.reduce((sum: number, item: unknown) => sum + countCharactersForPricing(item, options), 0);
  }
  if (typeof value === "object") {
    const record = value as Record<string, unknown>;
    if (typeof record.text === "string") {
      return ignoreWhitespace ? record.text.replace(/\s+/g, "").length : record.text.length;
    }
    return Object.values(record).reduce((sum: number, item: unknown) => sum + countCharactersForPricing(item, options), 0);
  }
  return 0;
}

function countItemsForPricing(value: unknown): number {
  if (value === null || value === undefined) return 0;
  if (Array.isArray(value)) return value.length;
  if (typeof value === "string") return value.trim().length > 0 ? 1 : 0;
  return 1;
}

function measurePricingUnits(
  value: unknown,
  metric: string,
  options: { ignoreWhitespace?: boolean } = {},
): number {
  if (metric === "items") {
    return countItemsForPricing(value);
  }
  return countCharactersForPricing(value, options);
}

const API_CONFIG_KEYS_ALLOWING_WHITESPACE_VALUES = new Set([
  "text_prefix",
  "textPrefix",
  "audio_text_prefix",
  "audioTextPrefix",
  "input_text_prefix",
  "inputTextPrefix",
  "text_suffix",
  "textSuffix",
  "audio_text_suffix",
  "audioTextSuffix",
  "input_text_suffix",
  "inputTextSuffix",
]);

function setApiConfigValue(apiConfig: Record<string, string>, key: string, value: unknown): void {
  if (value === null || value === undefined) return;
  if (typeof value === "string") {
    if (API_CONFIG_KEYS_ALLOWING_WHITESPACE_VALUES.has(key)) {
      if (value.length > 0) {
        apiConfig[key] = value;
      }
      return;
    }
    const normalized = value.trim();
    if (normalized.length > 0) {
      apiConfig[key] = normalized;
    }
    return;
  }
  if (typeof value === "number" || typeof value === "boolean") {
    apiConfig[key] = String(value);
  }
}

function buildApiConfigFromModelConfig(modelConfig: Record<string, unknown> | null | undefined): Record<string, string> {
  const apiConfig: Record<string, string> = {};
  if (!modelConfig || typeof modelConfig !== "object") {
    return apiConfig;
  }
  setApiConfigValue(apiConfig, "endpoint", modelConfig.apiEndpoint);
  setApiConfigValue(apiConfig, "query_endpoint", modelConfig.apiQueryEndpoint);
  setApiConfigValue(apiConfig, "payload_format", modelConfig.apiPayloadFormat);
  setApiConfigValue(apiConfig, "kie_model_id", modelConfig.kieModelId);
  setApiConfigValue(apiConfig, "generate_type", modelConfig.generateType);
  setApiConfigValue(apiConfig, "veo_4k_endpoint", modelConfig.veo4kEndpoint);
  setApiConfigValue(apiConfig, "veo_4k_endpoint", modelConfig.veo4KEndpoint);
  setApiConfigValue(apiConfig, "veo_4k_endpoint", modelConfig.veo4kUpgradeEndpoint);
  setApiConfigValue(apiConfig, "veo_4k_endpoint", modelConfig.veo4KUpgradeEndpoint);

  const customApiConfig = modelConfig.apiConfig;
  if (customApiConfig && typeof customApiConfig === "object" && !Array.isArray(customApiConfig)) {
    for (const [key, value] of Object.entries(customApiConfig as Record<string, unknown>)) {
      setApiConfigValue(apiConfig, key, value);
    }
  }

  return apiConfig;
}

function parseMediaModelConfig(configJson: unknown): Record<string, unknown> | null {
  if (!configJson) return null;
  if (typeof configJson === "string") {
    try {
      const parsed = JSON.parse(configJson);
      return parsed && typeof parsed === "object" && !Array.isArray(parsed)
        ? parsed as Record<string, unknown>
        : null;
    } catch {
      return null;
    }
  }
  return typeof configJson === "object" && !Array.isArray(configJson)
    ? configJson as Record<string, unknown>
    : null;
}

function getMediaModelCandidateIds(model: any): string[] {
  const config = parseMediaModelConfig(model?.configJson);
  const apiConfig = parseMediaModelConfig(config?.apiConfig);
  return [
    model?.modelId,
    model?.id,
    config?.providerModelId,
    apiConfig?.provider_model_id,
    apiConfig?.model,
    ...(Array.isArray(model?.aliases) ? model.aliases : []),
  ]
    .map((value) => String(value ?? "").trim())
    .filter(Boolean);
}

function hasAnyModelIdCandidate(model: any, allowedIds: Set<string>): boolean {
  const normalizedAllowed = new Set(Array.from(allowedIds, (id) => id.trim().toLowerCase()));
  return getMediaModelCandidateIds(model).some((id) => {
    const normalized = id.toLowerCase();
    if (normalizedAllowed.has(normalized)) return true;
    if (normalized.startsWith("wavespeed/")) {
      return normalizedAllowed.has(normalized.replace(/^wavespeed\//, "google/"));
    }
    if (normalized.startsWith("google/")) {
      return normalizedAllowed.has(normalized.replace(/^google\//, "wavespeed/"));
    }
    return false;
  });
}

function hasCandidateIdContaining(model: any, token: string): boolean {
  const normalizedToken = token.trim().toLowerCase();
  if (!normalizedToken) return false;
  return getMediaModelCandidateIds(model).some((id) => id.toLowerCase().includes(normalizedToken));
}

